use serde_json::{Value, json};
use t3_client::thread_views::document::{AtomKind, collect_atoms};
#[test]
fn token_boundaries_and_payloads_match_the_original_composer() {
    let cases: Value = serde_json::from_str(GOLDENS).expect("valid fixture");
    let mut failures = Vec::new();
    for case in cases.as_array().expect("valid fixture") {
        let source = case["text"].as_str().expect("valid fixture");
        let tokens=collect_atoms(source).iter().map(|atom|json!({"start":atom.range.start,"end":atom.range.end,"source":atom.source,"kind":match atom.kind {AtomKind::Mention=>"mention",AtomKind::Skill=>"skill",AtomKind::Model=>"model",AtomKind::Citation=>"citation",AtomKind::ContextReference=>"context-reference"},"value":atom.value})).collect::<Vec<_>>();
        if json!(tokens) != case["tokens"] {
            failures.push(format!(
                "{source:?}\nactual {}\nexpected {}",
                json!(tokens),
                case["tokens"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 20:\n{}",
        failures.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
